CREATE TABLE calendar_sync_state(account TEXT NOT NULL,calendar_id TEXT NOT NULL,query_fingerprint TEXT NOT NULL,time_zone TEXT NOT NULL,access TEXT NOT NULL,sync_token TEXT,revision INTEGER NOT NULL,PRIMARY KEY(account,calendar_id),FOREIGN KEY(account) REFERENCES accounts(id));
CREATE TABLE calendar_event_state(account TEXT NOT NULL,calendar_id TEXT NOT NULL,event_id TEXT NOT NULL,visible INTEGER NOT NULL DEFAULT 1,observed_json TEXT NOT NULL,PRIMARY KEY(account,calendar_id,event_id),FOREIGN KEY(account,calendar_id,event_id) REFERENCES calendar_sources(account,calendar_id,event_id));
CREATE TABLE calendar_batch_commits(account TEXT NOT NULL,calendar_id TEXT NOT NULL,expected_revision INTEGER NOT NULL,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(account,calendar_id,expected_revision),FOREIGN KEY(account,calendar_id) REFERENCES calendar_sync_state(account,calendar_id));
CREATE TABLE calendar_write_operations(account TEXT NOT NULL,request_id TEXT NOT NULL,fingerprint TEXT NOT NULL,intent_json TEXT NOT NULL,result_json TEXT,PRIMARY KEY(account,request_id),FOREIGN KEY(account) REFERENCES accounts(id));
INSERT INTO calendar_sync_state(account,calendar_id,query_fingerprint,time_zone,access,sync_token,revision) SELECT DISTINCT account,calendar_id,'fixture-calendar-v1','America/Toronto','reader',NULL,0 FROM calendar_sources;
INSERT INTO calendar_event_state(account,calendar_id,event_id,visible,observed_json) SELECT account,calendar_id,event_id,1,json FROM calendar_sources;
